// The integrations-core catalog (BSD-3-Clause, see integrations-core.LICENSE), generated by
// scripts/import-integration-catalog.mjs: one entry per integration's manifest.json, and the
// resolved configuration spec of each Agent check, loaded when its integration is opened.
import generated from './catalog.generated.json';
import type { SpecFile } from './agentConfig';
import type { Collection } from './collection';

export interface CoreIntegration {
  /** The manifest's app_id (the check name where several checks share one). */
  id: string;
  /** The integrations-core directory and Agent check name (conf.d/<check>.d/). */
  check: string;
  name: string;
  publisher: string;
  description: string;
  categories: string[];
  supportedOs: string[];
  offerings: string[];
  dataTypes: string[];
  metricPrefix: string | null;
  checkMetrics: string[];
  processSignatures: string[];
  logSource: string | null;
  dashboards: string[];
  monitors: string[];
  configurable: boolean;
  /** Prefix that identifies the integration in received metrics; null when shared or generic. */
  detectionPrefix: string | null;
  /** Where it comes from: Datadog's integrations-core, or integrations-extras (community and partners). */
  repository: Repository;
  /** How Datadog collects it (see collection.ts). */
  collection: Collection;
  /** A push-site sender that also takes any URL. */
  customEndpoint?: boolean;
}

export type Repository = 'integrations-core' | 'integrations-extras';

/** What integrations-core documents about an integration, as Datadog's integration page shows it. */
export interface IntegrationDocs {
  /** `DataDog/integrations-core@<sha> <directory>`. */
  source: string;
  /** README sections (Markdown, reference links included). */
  overview: string;
  setup: string;
  troubleshooting: string;
  furtherReading: string;
  resources: { type: string; url: string }[];
  metrics: { name: string; type: string; unit?: string; perUnit?: string; description: string }[];
  logFacets: { name: string; path: string; facetType: string; group: string }[];
  serviceChecks: { check: string; name: string; statuses: string[]; description: string }[];
  monitors: { title: string; description: string; type: string; query: string }[];
  dashboards: { key: string; title: string; file: string }[];
  releaseNotes: { version: string; date: string; notes: string }[];
}

export const coreCatalog = generated as { source: string; integrations: CoreIntegration[] };

const specs = import.meta.glob<SpecFile>('./agentSpecs/*.json', { import: 'default' });

const docs = import.meta.glob<IntegrationDocs>('./details/*.json', { import: 'default' });

/** An integration's documentation and assets from integrations-core (scripts/import-integration-details.mjs), or null. */
export async function loadIntegrationDocs(id: string): Promise<IntegrationDocs | null> {
  const load = docs[`./details/${id}.json`];
  return load ? load() : null;
}

/** The check's configuration spec, or null when integrations-core has none. */
export async function loadAgentSpec(check: string): Promise<SpecFile | null> {
  const load = specs[`./agentSpecs/${check}.json`];
  return load ? load() : null;
}
